-- The reporting periods the staged sources compute for: one row per period. Every case uses the first half of 2026.
CREATE SCHEMA gasp;
CREATE TABLE gasp.period_spine (period_start DATE, period_end DATE);

-- GASP dataset revenue_event (event; Revenue event). rows dated from 2025-12-01
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.revenue_event (
  change_nature VARCHAR(1000),
  currency VARCHAR(1000),
  customer_id VARCHAR(1000),
  event_date DATE,
  event_id VARCHAR(1000),
  event_type VARCHAR(1000),
  expansion_classification VARCHAR(1000),
  lifecycle_attribution VARCHAR(1000),
  mrr_change DECIMAL(18, 6),
  new_mrr DECIMAL(18, 6),
  prior_mrr DECIMAL(18, 6),
  segment VARCHAR(1000),
  subscription_id VARCHAR(1000)
);

-- GASP dataset cost_event (event; Cost event). rows dated from 2025-12-01
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.cost_event (
  cost DECIMAL(18, 6),
  cost_centre VARCHAR(1000),
  cost_function VARCHAR(1000),
  cost_type VARCHAR(1000),
  currency VARCHAR(1000),
  customer_id VARCHAR(1000),
  event_date DATE,
  event_id VARCHAR(1000),
  lifecycle_attribution VARCHAR(1000),
  partner_id VARCHAR(1000),
  project_id VARCHAR(1000)
);

-- GASP dataset customer (snapshot; Customer). snapshot rows on month starts, month ends and the period bounds shifted back by one, three, six and twelve months
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.customer (
  acquisition_date DATE,
  activation_date DATE,
  composite_score DECIMAL(18, 6),
  criteria_met BOOLEAN,
  csm_id VARCHAR(1000),
  customer_id VARCHAR(1000),
  customer_status VARCHAR(1000),
  last_active_date DATE,
  onboarding_completion_date DATE,
  qbr_completed BOOLEAN,
  qbr_due BOOLEAN,
  segment VARCHAR(1000),
  snapshot_date DATE,
  upgrade_eligible BOOLEAN
);

-- GASP dataset subscription (snapshot; Subscription). snapshot rows on month starts, month ends and the period bounds shifted back by one, three, six and twelve months
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.subscription (
  auto_renewed BOOLEAN,
  contract_end DATE,
  contract_start DATE,
  customer_id VARCHAR(1000),
  forecast_renewal_amount DECIMAL(18, 6),
  plan_id VARCHAR(1000),
  mrr DECIMAL(18, 6),
  mrr_end DECIMAL(18, 6),
  mrr_start DECIMAL(18, 6),
  renewal_amount DECIMAL(18, 6),
  renewal_complete_date DATE,
  renewal_notified_on_time BOOLEAN,
  renewal_trigger_date DATE,
  renewed BOOLEAN,
  segment VARCHAR(1000),
  snapshot_date DATE,
  subscription_id VARCHAR(1000),
  subscription_status VARCHAR(1000)
);

-- GASP dataset survey_response (event; Survey response). rows dated from 2025-12-01
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.survey_response (
  ces_score INTEGER,
  customer_id VARCHAR(1000),
  employee_id VARCHAR(1000),
  engagement_score DECIMAL(18, 6),
  lead_id VARCHAR(1000),
  nps_score INTEGER,
  partner_id VARCHAR(1000),
  project_id VARCHAR(1000),
  response_id VARCHAR(1000),
  satisfaction_score INTEGER,
  survey_completed BOOLEAN,
  survey_date DATE,
  survey_type VARCHAR(1000)
);

-- GASP dataset financials (fact; Income statement and cash flow). rows dated from 2025-12-01
-- Generated from the GASP test fixture (gasp-wiki-mcp/test/fixture/generate.ts, seed 20260101) by npm run conformance.
CREATE TABLE gasp.financials (
  bad_debt_expense DECIMAL(18, 6),
  capital_expenditures DECIMAL(18, 6),
  ebitda DECIMAL(18, 6),
  net_income DECIMAL(18, 6),
  operating_cash_flow DECIMAL(18, 6),
  period_start DATE,
  revenue DECIMAL(18, 6),
  revenue_type VARCHAR(1000)
);
